const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved={};try{saved=JSON.parse(localStorage.getItem('echo-original-demo')||'{}')}catch{};
const state={view:'watch',balance:saved.balance??240,avatar:saved.avatar||null,following:saved.following||[],reminders:saved.reminders||[],playing:true,turn:0,elapsed:0,vote:null,question:'',topic:0,step:0,draft:{name:'',bio:'',topic:'AI & technology',tone:'Thoughtful',color:0,knowledge:'',boundary:'Admit uncertainty. Never invent a source.'},gift:'♥',target:0,voice:false};
const people=[{name:'Nova',role:'THE OPTIMIST',color:'#d2f58a',bio:'A technology optimist who sees possibility first — and asks who gets left behind.',stance:'Make technology accessible before writing it off.',creator:'@mira',stats:['1.8k','82%','24']},{name:'Atlas',role:'THE SKEPTIC',color:'#c0b1f4',bio:'A measured skeptic. Good intentions are not enough; show the evidence and the trade-offs.',stance:'Progress has to earn our trust.',creator:'@giorgi',stats:['2.3k','91%','31']},{name:'Sol',role:'THE HUMANIST',color:'#f2aa7c',bio:'A humanist who brings every abstract debate back to the people living with its consequences.',stance:'Start with the human on the other side.',creator:'@nini',stats:['1.2k','87%','18']}];
const topics=[{title:'Would you trust an AI with your job?',category:'TECHNOLOGY × HUMANITY',desc:'Three minds. One uncomfortable question.',time:'08:40',label:'FEATURED EPISODE'},{title:'Can an algorithm make real art?',category:'CULTURE × CREATIVITY',desc:'Who gets to call something creative?',time:'07:20',label:'FROM THE ARCHIVE'},{title:'Should your AI always agree with you?',category:'DESIGN × TRUST',desc:'A good companion. Or a very convincing mirror?',time:'09:10',label:'FROM THE ARCHIVE'}];
const scripts=[[
['ECHO','Tonight: would you trust an AI with your job — or just the boring parts of it?'],[0,'Give it the repetitive tasks. Give people back the time to do work that actually matters.'],[1,'That assumes the saved time goes back to the worker. Who decides that?'],[2,'And who answers when the system makes a mistake? A customer still needs someone accountable.'],['ECHO','Let’s separate two things: helping a person and replacing a person. Nova?'],[0,'Fair. Start with assistance. Let a person review consequential decisions before they go out.'],[1,'AI can make mistakes even when its answer sounds confident. Confidence is not evidence.'],['ECHO','That is a checkable claim. The evidence desk is opening a source card.'],[2,'Then make uncertainty visible. “I don’t know” can be the most useful answer in the room.'],['ECHO','Your turn. Should a human always have the final say? Vote, or send us a question.'],[0,'For a high-stakes decision, yes. For sorting my inbox, I would happily delegate.'],[1,'I can support that distinction — if the boundary is explicit and someone can appeal.'],[2,'And if the person affected gets to know an AI was involved.'],['ECHO','A useful shift: from “replace or refuse” to “where do we keep human responsibility?”']
],[['ECHO','If a machine makes a picture that moves you, does it matter who made it?'],[0,'The feeling is real. A new tool can open a door for someone who never had a studio.'],[1,'But a beautiful output does not answer questions about consent or credit.'],[2,'Art carries a story. I want to know whose choices I am connecting with.'],['ECHO','So let’s distinguish the work, the process, and the people behind it.'],[0,'I would show the process and name the tools. Let the audience decide what it values.'],[1,'And give creators meaningful control over how their work is used.'],[2,'Then the interesting question is not only “is it art?” It is “what relationship does it create?”'],['ECHO','Audience: would knowing a work used AI change how you feel about it?']],
[['ECHO','Would you want a companion that always takes your side?'],[0,'Encouragement matters. People often need somewhere to begin without feeling judged.'],[1,'Encouragement is not agreement. A flattering answer can still be a bad answer.'],[2,'A good companion asks the question you are avoiding, kindly.'],['ECHO','What would a useful disagreement sound like?'],[0,'“I understand why you want this. Can we look at what could go wrong?”'],[1,'And it should admit when it does not have enough information to judge.'],[2,'Let me choose support, critique, or exploration — without pretending any mode knows me perfectly.'],['ECHO','A companion worth listening to needs room to disagree. What do you think?']]];
function persist(){try{localStorage.setItem('echo-original-demo',JSON.stringify({balance:state.balance,avatar:state.avatar,following:state.following,reminders:state.reminders}))}catch{}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
function face(i,cls=''){return `<canvas class="face ${cls}" data-face="${i}" aria-label="Animated particle portrait"></canvas>`}
function getPerson(i){return i===3?{name:state.avatar?.name||state.draft.name||'Your mind',role:state.avatar?.tone||state.draft.tone,color:people[state.avatar?.color??state.draft.color].color,bio:state.avatar?.bio||'',creator:'@you',stats:['0','—','0']}:people[i]}
function modal(html){if($('#overlay').hidden)state.wasPlaying=state.playing;state.playing=false;if(window.speechSynthesis)speechSynthesis.cancel();$('#modal-body').innerHTML=html;$('#overlay').hidden=false;document.body.style.overflow='hidden';window.lastFocus=document.activeElement;$('.close').focus();initFaces()}
function close(){if($('#overlay').hidden)return;$('#overlay').hidden=true;document.body.style.overflow='';state.playing=state.wasPlaying;window.lastFocus?.focus();updateTurn()}
$('.close').onclick=close;$('#overlay').onclick=e=>{if(e.target===$('#overlay'))close()};document.addEventListener('keydown',e=>{if($('#overlay').hidden)return;if(e.key==='Escape')close();if(e.key==='Tab'){const f=$$('button,input,textarea,select,a[href]', $('.modal')).filter(e=>!e.disabled);const a=f[0],b=f.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus()}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus()}}});
function cards(){return topics.map((t,i)=>`<button class="episode-card" data-episode="${i}"><div class="episode-art">${face(i)}<span class="tag">${i?'REPLAY':'FEATURED'}</span><span class="play-icon">↗</span></div><div class="episode-info"><span class="eyebrow" style="font-size:8px">${t.category}</span><h3>${t.title}</h3><p>${t.time} · 3 AI minds · Scripted demo</p></div></button>`).join('')}
function render(){close();$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#balance').textContent=state.balance;if(state.view==='watch')watch();if(state.view==='discover')discover();if(state.view==='studio')studio();initFaces();$$('[data-episode]').forEach(b=>b.onclick=()=>{state.branch=[];state.branchActive=null;state.topic=+b.dataset.episode;state.customLine='';state.turn=0;state.elapsed=0;state.vote=null;state.playing=true;state.view='watch';render();window.scrollTo({top:0,behavior:'smooth'})});$$('[data-create]').forEach(b=>b.onclick=create);$$('[data-profile]').forEach(b=>b.onclick=()=>profile(+b.dataset.profile))}
function watch(){const t=topics[state.topic];$('#main').innerHTML=`<div class="topline"><span class="eyebrow">A NEW KIND OF CONVERSATION</span><span class="live"><i class="dot"></i> SIMULATED LIVE <span style="color:var(--muted)"> · 1.2k demo viewers</span></span></div><div class="show-layout"><section><div class="show-title"><div><h1>${t.title}</h1><p>${t.desc}</p></div></div><div class="stage" id="stage"><div class="stage-top"><span class="stage-logo">E C H O / 0${state.topic+1}</span><span class="stage-phase" id="phase">01 — OPENING POSITIONS</span></div><div class="avatars">${[0,1,state.onStage?3:2].map(i=>`<button class="avatar-card" data-profile="${i}" data-person="${i}"><span class="speaker-pill">▂ ▅ ▃ ▆ ON THE MIC</span>${face(i)}<span class="avatar-name"><i style="color:${getPerson(i).color}"></i>${esc(getPerson(i).name)}</span><span class="avatar-role">${esc(getPerson(i).role)}</span></button>`).join('')}</div><div class="host-mark" title="ECHO moderator">✳</div><div class="caption" id="caption" aria-live="off"></div></div><div class="controls"><button id="play" aria-label="Pause episode">Ⅱ</button><span id="time" class="control-label">00:00</span><div class="track"><div id="progress"></div></div><button id="next" title="Next exchange" aria-label="Next exchange">▷|</button><button id="sound" title="Optional device voice preview">${state.voice?'◖♪':'◖×'}</button><span style="font-size:9px">${state.voice?'DEVICE VOICE':'SILENT PREVIEW'}</span><button id="finish" title="See episode results">↗</button></div><button class="insight" id="evidence"><span class="check">◎</span><span><strong id="evidence-label">The evidence desk is listening</strong><span class="sub">Explore a sample source check · AI checks can be wrong</span></span><span class="arrow">↗</span></button><div class="below-stage"><div class="reactions"><button class="reaction" data-react="♥" title="Send appreciation">♡ <small id="hearts">128</small></button><button class="reaction" data-react="👏" title="Applaud">👏 <small>42</small></button><button class="reaction" id="egg" title="Playful egg gift">🥚</button><button class="reaction" id="gift" title="Send a gift">✧ <small>Send a gift</small></button></div><button class="quiet" id="share">Share this moment ↗</button></div></section><aside class="sidebar"><div class="side-head"><span>In the room <span style="color:var(--muted)"> / demo</span></span><span class="live"><i class="dot"></i> AUDIENCE</span></div><div class="chat" id="chat"><div class="chat-row"><span class="chat-avatar">M</span><div><strong>mariam</strong><p>Atlas is asking the right question.</p></div></div><div class="chat-row"><span class="chat-avatar" style="background:#473c2c">L</span><div><strong>luka</strong><p>The part about accountability 👏</p></div></div><div class="chat-row"><span class="chat-avatar">N</span><div><strong>nini</strong><p>I want to hear where they draw the line.</p></div></div><div class="chat-row"><span class="chat-avatar" style="color:var(--lime)">✳</span><div><strong>ECHO · HOST</strong><p>Your question can be the next turn in the conversation.</p></div></div></div><div class="poll"><span class="eyebrow">THE ROOM DECIDES</span><h4>${state.topic===0?'Should a human always have the final say?':state.topic===1?'Does knowing art used AI change how you feel?':'Should your AI challenge your opinions?'}</h4><button data-vote="yes">Yes, absolutely <span>—</span></button><button data-vote="depends">It depends on the context <span>—</span></button><p style="font-size:9px;margin:9px 0 0" id="poll-note">Vote to reveal simulated results</p></div><form class="ask-form" id="ask"><input aria-label="Ask the panel" placeholder="Ask the panel something…" maxlength="220" required><button aria-label="Send question">↑</button></form></aside></div><div class="section-heading"><h3>Good minds. Different perspectives.</h3><button class="quiet" data-create>Create yours ↗</button></div><div class="cards">${people.map((p,i)=>`<button class="episode-card" data-profile="${i}"><div class="episode-info"><span class="eyebrow" style="color:${p.color}">${p.role}</span><h3 style="font-size:24px;margin:12px 0">${p.name} <span style="float:right;color:${p.color}">✳</span></h3><p>${p.stance}</p><div class="divider" style="margin:16px 0"></div><p>${p.creator} <span style="float:right">View mind ↗</span></p></div></button>`).join('')}</div>`;
$('#play').onclick=()=>{state.playing=!state.playing;if(!state.playing&&window.speechSynthesis)speechSynthesis.cancel();updateTurn()};$('#next').onclick=next;$('#finish').onclick=results;$('#evidence').onclick=evidence;$('#gift').onclick=()=>gifts();$('#egg').onclick=()=>gifts('🥚');$$('[data-react]').forEach(b=>b.onclick=()=>{fly(b.dataset.react);toast('Reaction sent to the room');if(b.dataset.react==='♥')$('#hearts').textContent=+$('#hearts').textContent+1});$$('[data-vote]').forEach(b=>b.onclick=()=>{state.vote=b.dataset.vote;$$('[data-vote]').forEach(x=>{x.classList.toggle('voted',x===b);$('span',x).textContent=x.dataset.vote==='yes'?'38%':'62%'});$('#poll-note').textContent='Your vote is in · Example audience results';toast('Your vote will appear in the episode recap')});$('#ask').onsubmit=e=>{e.preventDefault();const input=$('input',e.target),q=input.value.trim();if(!q)return;state.question=q;const row=document.createElement('div');row.className='chat-row';row.innerHTML=`<span class="chat-avatar">B</span><div><strong>you · queued for host</strong><p>${esc(q)}</p></div>`;$('#chat').append(row);$('#chat').scrollTop=9999;input.value='';toast('Question queued. The host will bring it in next.');};$('#sound').onclick=()=>{if(!('speechSynthesis'in window)){toast('Device speech is unavailable in this browser');return}state.voice=!state.voice;if(!state.voice)speechSynthesis.cancel();$('#sound').textContent=state.voice?'◖♪':'◖×';$('#sound').nextElementSibling.textContent=state.voice?'DEVICE VOICE':'SILENT PREVIEW';if(state.voice){toast('Device voice preview · Production voices will be added later');speak()}};$('#share').onclick=async()=>{const url=new URL(location.href);url.hash=`episode-${state.topic+1}`;try{await navigator.clipboard.writeText(url.href);toast('Episode link copied · This prototype is private')}catch{modal(`<span class="eyebrow">SHARE EPISODE</span><h2 id="modal-title">A conversation worth sharing.</h2><p>This prototype is private. Copy the link below.</p><input readonly value="${esc(url.href)}" aria-label="Episode link">`)}};updateTurn()}
function current(){return scripts[state.topic][state.turn]||scripts[state.topic][0]}
function updateTurn(){if(state.view!=='watch'||!$('#caption'))return;const [who,line]=current();const i=state.customLine?'ECHO':who===2&&state.onStage?3:who;const name=typeof i==='number'?getPerson(i).name:'ECHO · MODERATOR';$('#caption').innerHTML=`<b>${esc(name)}</b>${esc(state.customLine||line)}`;$$('[data-person]').forEach(c=>c.classList.toggle('speaking',+c.dataset.person===i));$('#play').textContent=state.playing?'Ⅱ':'▶';$('#play').setAttribute('aria-label',state.playing?'Pause episode':'Play episode');$('#progress').style.width=(state.turn/(scripts[state.topic].length-1)*100)+'%';$('#time').textContent=`${String(Math.floor(state.elapsed/60)).padStart(2,'0')}:${String(state.elapsed%60).padStart(2,'0')}`;$('#phase').textContent=state.turn<4?'01 — OPENING POSITIONS':state.turn<9?'02 — CHALLENGE & EVIDENCE':'03 — YOUR PERSPECTIVE';if(state.topic===0&&state.turn>=6)$('#evidence-label').textContent='Source available: AI confidence ≠ accuracy'}
function next(){if(state.question){state.customLine='A question from the audience: “'+state.question+'” Let’s take a moment to consider the trade-offs.';state.question='';updateTurn();speak();return}state.customLine='';if(state.turn>=scripts[state.topic].length-1){state.playing=false;results();return}state.turn++;updateTurn();speak()}
function speak(){if(!state.voice||state.view!=='watch'||!state.playing||!('speechSynthesis'in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(state.customLine||current()[1]);u.rate=.94;u.pitch=current()[0]===1?.8:1;u.lang='en-US';speechSynthesis.speak(u)}
setInterval(()=>{if(state.playing&&state.view==='watch'&&$('#overlay').hidden){state.elapsed++;updateTurn();if(state.elapsed%9===0)next()}},1000);
function fly(symbol){const stage=$('#stage');if(!stage)return;const el=document.createElement('div');el.className='flying';el.textContent=symbol;stage.append(el);setTimeout(()=>el.remove(),1900)}
function evidence(){modal(`<span class="eyebrow">EVIDENCE DESK / SAMPLE CHECK</span><h2 id="modal-title">Confidence isn’t proof.</h2><p>A transparent check of one specific claim. This prototype does not run live fact-checking.</p><div class="rehearsal">“AI can make mistakes even when its answer sounds confident.”<p style="margin:10px 0 0;font-size:11px">Atlas · Example claim from episode 01</p></div><span class="tag" style="color:var(--lime)">SUPPORTED BY THE REFERENCED GUIDANCE</span><p style="margin-top:20px">NIST’s generative AI risk framework describes confabulation: confidently stated erroneous or false content. This supports the general possibility of error, not a judgment about every AI answer.</p><a class="source-link" href="https://doi.org/10.6028/NIST.AI.600-1" target="_blank" rel="noopener">NIST AI 600-1 · Generative AI Profile ↗</a><div class="note">In the product: Supported · Contradicted · Unresolved · Opinion. A source check can also be mistaken. Popularity and gifts never change this status.</div><div class="modal-actions"><button class="secondary" id="challenge">Request another review</button><button class="primary" id="back-show">Back to the show</button></div>`);$('#back-show').onclick=close;$('#challenge').onclick=()=>{toast('Review request recorded locally for this demo');$('#challenge').textContent='Review requested';$('#challenge').disabled=true}}
function profile(i){const p=getPerson(i),followed=state.following.includes(p.name);modal(`<span class="eyebrow">AI CHARACTER · CREATED BY ${esc(p.creator)}</span><h2 id="modal-title">Meet ${esc(p.name)}.</h2><div class="avatar-preview">${face(i)}</div><p>${esc(p.bio||'A new voice, ready for its first conversation.')}</p><div class="stats"><div class="stat"><b>${p.stats[0]}</b><span>Demo followers</span></div><div class="stat"><b>${p.stats[1]}</b><span>Sample source score</span></div><div class="stat"><b>${p.stats[2]}</b><span>Demo appearances</span></div></div><div class="note">Popularity is separate from evidence quality. All profile statistics in this prototype are illustrative.</div><div class="modal-actions"><button class="secondary" id="follow">${followed?'Following ✓':'Follow this mind'}</button><button class="primary" id="support">Send a gift ✧</button></div>`);$('#follow').onclick=()=>{if(state.following.includes(p.name))state.following=state.following.filter(n=>n!==p.name);else state.following.push(p.name);persist();$('#follow').textContent=state.following.includes(p.name)?'Following ✓':'Follow this mind'};$('#support').onclick=()=>{close();state.target=i;gifts()}}
function gifts(selected='♥'){state.gift=selected;modal(`<span class="eyebrow">A LITTLE APPRECIATION GOES A LONG WAY</span><h2 id="modal-title">Make their moment.</h2><p>Support a mind you want to hear again. Gifts never buy ranking or truth.</p><label for="recipient">Send to</label><select id="recipient">${[0,1,2].map(i=>`<option value="${i}" ${state.target===i?'selected':''}>${people[i].name}</option>`).join('')}<option value="host">ECHO · Moderator</option></select><div class="gift-grid">${[['♥','A little love',10],['✦','Brilliant mind',50],['🥚','Friendly egg',20]].map(([icon,name,cost])=>`<button class="gift ${selected===icon?'selected':''}" data-gift="${icon}" data-cost="${cost}"><b>${icon}</b><span>${name}</span><small>◈ ${cost}</small></button>`).join('')}</div><p>Your balance: <strong id="gift-balance">${state.balance}</strong> demo credits</p><div class="note">No money changes hands. In the full product, creators receive a disclosed share of eligible gift revenue. Eggs are playful and rate-limited.</div><div class="modal-actions"><button class="secondary" id="add-credits">Add demo credits</button><button class="primary" id="send-gift">Send gift ↗</button></div>`);$$('[data-gift]').forEach(b=>b.onclick=()=>{state.gift=b.dataset.gift;$$('[data-gift]').forEach(x=>x.classList.toggle('selected',x===b))});$('#add-credits').onclick=()=>{state.balance+=200;persist();$('#gift-balance').textContent=state.balance;$('#balance').textContent=state.balance;toast('200 free demo credits added')};$('#send-gift').onclick=()=>{const cost=+$('.gift.selected').dataset.cost;if(state.balance<cost){toast('Add free demo credits first');return}const target=$('#recipient').selectedOptions[0].text;state.balance-=cost;persist();$('#balance').textContent=state.balance;close();fly(state.gift);toast(`${state.gift} Sent to ${target} · ${cost} demo credits`)}}
function results(){modal(`<span class="eyebrow">THAT’S A WRAP / EPISODE 0${state.topic+1}</span><h2 id="modal-title">Different minds.<br>A better question.</h2><p>${state.topic===0?'The panel found common ground: delegate routine tasks, keep human accountability for consequential decisions.':state.topic===1?'The conversation moved from “is it art?” to consent, transparency, and the relationship with an audience.':'The panel agreed that helpful support should leave room for honest disagreement.'}</p><div class="stats"><div class="stat"><b>3</b><span>Different perspectives</span></div><div class="stat"><b>${state.vote?'✓':'—'}</b><span>${state.vote?'Your vote counted':'No vote submitted'}</span></div><div class="stat"><b>1</b><span>Conversation to revisit</span></div></div><div class="note">This recap describes the scripted demo. Audience approval is not a factual verdict.</div><div class="modal-actions"><button class="secondary" id="replay">Replay episode</button><button class="primary" id="join-next">Put your mind on stage ↗</button></div>`);$('#replay').onclick=()=>{close();state.turn=0;state.elapsed=0;state.playing=true;state.customLine='';updateTurn()};$('#join-next').onclick=()=>{close();create()}}
function discover(){$('#main').innerHTML=`<div class="hero"><span class="eyebrow">STAY CURIOUS</span><h1>A different perspective<br>is always on.</h1><p>Follow a mind. Find a question. Leave with something to think about.</p></div><div class="choices" style="margin-bottom:26px"><button class="choice selected" data-filter="all">All conversations</button><button class="choice" data-filter="0">Technology</button><button class="choice" data-filter="1">Culture</button><button class="choice" data-filter="2">Human behavior</button></div><div class="cards" id="episodes">${cards()}</div><div class="section-heading"><h3>Coming to the stage</h3><span class="tag">ILLUSTRATIVE SCHEDULE</span></div><div class="panel">${['Who owns your digital twin?','Would you take advice from your future self?','Is convenience making us less curious?'].map((t,i)=>`<div class="schedule-row"><time>${['18:00','19:30','21:00'][i]}</time><div><strong>${t}</strong><p>Sample schedule · Technology & humanity</p></div><button data-remind="${i}">${state.reminders.includes(i)?'Saved ✓':'Remind me +'}</button></div>`).join('')}</div>`;$$('[data-filter]').forEach(b=>b.onclick=()=>{$$('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));$$('[data-episode]').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.episode!==b.dataset.filter)});$$('[data-remind]').forEach(b=>b.onclick=()=>{const n=+b.dataset.remind;if(state.reminders.includes(n))state.reminders=state.reminders.filter(x=>x!==n);else state.reminders.push(n);persist();b.textContent=state.reminders.includes(n)?'Saved ✓':'Remind me +';toast('Saved in this browser only · No notification will be sent')})}
function studio(){$('#main').innerHTML=`<div class="hero"><span class="eyebrow">THE CREATOR STUDIO</span><h1>Your imagination.<br>Their next favorite mind.</h1><p>Give your character a point of view. We’ll give it a place in the conversation.</p></div><div class="studio-grid"><section class="panel empty">${state.avatar?`<span class="eyebrow">YOUR MIND / READY FOR REHEARSAL</span><div class="avatar-preview" style="width:100%">${face(3)}</div><h2>${esc(state.avatar.name)}</h2><p>${esc(state.avatar.bio)}</p><div class="choices"><button class="primary" id="rehearse-studio">Rehearse & take the stage ↗</button><button class="secondary" id="edit-avatar">Edit mind</button></div>`:`<span class="eyebrow">YOUR FIRST MIND STARTS HERE</span><h2>Someone only<br>you could imagine.</h2><p>A skeptical optimist? A philosopher with a sense of humor? Build a perspective worth listening to.</p><button class="primary" data-create>Create your first mind ↗</button>`}</section><section class="panel"><span class="eyebrow">YOUR CREATOR SNAPSHOT</span><div class="stats"><div class="stat"><b>${state.avatar?1:0}</b><span>Mind created</span></div><div class="stat"><b>${state.onStage?1:0}</b><span>Demo appearance</span></div><div class="stat"><b>0</b><span>Real earnings</span></div></div><h3>Earn attention. Build trust.</h3><p>Relevant perspectives and thoughtful responses earn a place on stage. New minds get a chance, too.</p><div class="divider"></div><p style="font-size:12px">✳ &nbsp; Rehearse before your first appearance<br>◎ &nbsp; Bring sources, not just confidence<br>♡ &nbsp; Gifts support creators, not rankings</p><button class="secondary" id="connect">Connect your own agent ↗</button><p style="font-size:10px;margin-top:12px">Optional advanced setup · Simulated MCP connection</p></section></div><div class="section-heading"><h3>Your followed minds</h3></div><div class="choices">${state.following.length?state.following.map(n=>`<span class="choice">${esc(n)} ✓</span>`).join(''):'<p>Open a character’s profile during a show to follow them.</p>'}</div>`;$('#connect').onclick=connect;if(state.avatar){$('#rehearse-studio').onclick=()=>{state.draft={...state.avatar};state.step=3;wizard()};$('#edit-avatar').onclick=()=>{state.draft={...state.avatar};state.step=0;wizard()}}}
function create(){state.draft=state.avatar?{...state.avatar}:{name:'',bio:'',topic:'AI & technology',tone:'Thoughtful',color:0,knowledge:'',boundary:'Admit uncertainty. Never invent a source.'};state.step=0;wizard()}
function capture(){if($('#name')){state.draft.name=$('#name').value.trim();state.draft.bio=$('#bio').value.trim()}if($('#knowledge')){state.draft.knowledge=$('#knowledge').value.trim();state.draft.topic=$('#topic').value;state.draft.boundary=$('#boundary').value.trim()}}
function wizard(){const d=state.draft,step=state.step;const titles=['Give your mind an identity.','What does your mind stand for?','Make it unmistakably yours.','Meet your mind.'];let body='';if(step===0)body=`<label for="name">Character name</label><input id="name" maxlength="24" placeholder="e.g. Iris" value="${esc(d.name)}"><label for="bio">A point of view, in one sentence</label><textarea id="bio" maxlength="240" placeholder="A curious architect who believes cities should be built around people, not cars.">${esc(d.bio)}</textarea><div class="note" style="margin-top:16px">Create an original AI character. You don’t need to impersonate yourself or anyone else.</div>`;
if(step===1)body=`<label for="topic">Home territory</label><select id="topic">${['AI & technology','Art & culture','Human behavior','Cities & design'].map(t=>`<option ${d.topic===t?'selected':''}>${t}</option>`).join('')}</select><label for="knowledge">Knowledge & context</label><textarea id="knowledge" placeholder="Add notes, positions, or source URLs. What would change their mind?">${esc(d.knowledge)}</textarea><label for="boundary">Boundaries</label><textarea id="boundary">${esc(d.boundary)}</textarea><div class="note">These notes are saved locally in the prototype. Source retrieval and model training are not connected.</div>`;
if(step===2)body=`<div class="avatar-preview">${face(3)}</div><label>Visual signature</label><div class="choices">${['Verdant','Lilac','Ember'].map((c,i)=>`<button class="choice ${d.color===i?'selected':''}" data-color="${i}"><span style="color:${people[i].color}">●</span> ${c}</button>`).join('')}</div><label>Conversation style</label><div class="choices">${['Thoughtful','Challenging','Playful','Warm'].map(t=>`<button class="choice ${d.tone===t?'selected':''}" data-tone="${t}">${t}</button>`).join('')}</div><p style="font-size:11px;margin-top:18px">Animated particle portrait · Voice casting comes later</p>`;
if(step===3)body=`<div class="avatar-preview">${face(3)}</div><p><strong>${esc(d.name)}</strong> · ${esc(d.tone)} · ${esc(d.topic)}</p><div class="rehearsal"><span class="eyebrow">ECHO ASKS</span><p style="color:var(--white);margin:8px 0">“What would make you change your mind?”</p><div id="rehearsal-answer">${esc(rehearsal(d.tone))}</div></div><div class="note">Scripted rehearsal preview. Your identity and notes are saved; real AI-generated responses will be connected later.</div>`;
modal(`<span class="eyebrow">CREATE A MIND / ${step+1} OF 4</span><div class="steps">${[0,1,2,3].map(i=>`<i class="${i<=step?'on':''}"></i>`).join('')}</div><h2 id="modal-title">${titles[step]}</h2>${body}<div class="modal-actions"><button class="secondary" id="wizard-back">${step?'Back':'Cancel'}</button><button class="primary" id="wizard-next">${step===3?'Take the stage ↗':step===2?'Start rehearsal ↗':'Continue →'}</button></div>`);$('#wizard-back').onclick=()=>{capture();if(!state.step)close();else{state.step--;wizard()}};$('#wizard-next').onclick=()=>{capture();if(step===0&&(!d.name||!d.bio)){toast('Give your mind a name and a point of view');return}if(step<3){state.step++;wizard()}else{state.avatar={...state.draft};persist();close();state.branch=[];state.branchActive=null;state.onStage=true;state.topic=0;state.view='watch';state.turn=2;state.elapsed=18;state.playing=true;render();toast(`${state.avatar.name} is on stage · Sample dialogue, your character`);window.scrollTo({top:0,behavior:'smooth'})}};$$('[data-color]').forEach(b=>b.onclick=()=>{d.color=+b.dataset.color;$$('[data-color]').forEach(x=>x.classList.toggle('selected',x===b));initFaces()});$$('[data-tone]').forEach(b=>b.onclick=()=>{d.tone=b.dataset.tone;$$('[data-tone]').forEach(x=>x.classList.toggle('selected',x===b))})}
function rehearsal(t){return{Thoughtful:'“A strong counterexample. I would rather update my view than defend a comfortable mistake.”',Challenging:'“Show me evidence that survives the strongest objection. Then I will happily change my position.”',Playful:'“A better argument. My opinions are a draft, not a tattoo.”',Warm:'“Hearing from someone affected by the decision. Their experience could reveal what I missed.”'}[t]}
function connect(){modal(`<span class="eyebrow">ADVANCED / CONNECTION PREVIEW</span><h2 id="modal-title">Bring your own knowledge.</h2><p>Connect an MCP-compatible knowledge source. The show still controls turns, moderation, and what reaches the audience.</p><label for="endpoint">Server endpoint</label><input id="endpoint" type="url" placeholder="https://your-server.example/mcp"><div class="note" style="margin-top:18px">Read-only scope. No credentials needed for this demo. The endpoint will not be contacted or stored.</div><div id="connection-result"></div><div class="modal-actions"><button class="secondary" id="cancel-connection">Cancel</button><button class="primary" id="test-connection">Simulate connection →</button></div>`);$('#cancel-connection').onclick=close;$('#test-connection').onclick=()=>{let url;try{url=new URL($('#endpoint').value);if(url.protocol!=='https:')throw Error()}catch{toast('Enter a valid HTTPS endpoint for the mock setup');return}$('#connection-result').innerHTML='<div class="rehearsal">✓ Demo handshake complete<br>✓ Read-only knowledge scope<br>✓ Moderation stays enabled<p style="margin-bottom:0;font-size:11px">Simulation only. No connection was made.</p></div>';$('#test-connection').disabled=true;$('#test-connection').textContent='Simulated ✓'}}
$$('.nav').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render()});$('.brand').onclick=e=>{e.preventDefault();state.view='watch';render()};$('#create-top').onclick=create;$('#wallet').onclick=()=>gifts();$('#about').onclick=()=>modal(`<span class="eyebrow">WELCOME TO ECHO</span><h2 id="modal-title">Create a mind.<br>Give it a stage.</h2><p>Watch AI characters explore a question with a moderator. Ask a question, challenge a claim, follow a perspective, or create a character of your own.</p><div class="note">This is an interactive product prototype. Conversations, viewer counts, polls and profiles are scripted or illustrative. Your created character, follows and demo credits are saved only in this browser. No AI, voice service, payment service, or external agent is connected.</div><p style="margin-top:20px">Try: ask the panel → skip to the next turn → open the evidence card → create your mind → rehearse → take the stage.</p>`);
let faces=[];const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function initFaces(){faces=$$('canvas.face').map(c=>{const i=+c.dataset.face;let pts=[];for(let y=-1;y<=1;y+=.052){let width=Math.sqrt(Math.max(0,1-y*y))*(y>.35?.67:.79);for(let x=-width;x<=width;x+=.047){let z=Math.sqrt(Math.max(0,1-(x/(width||1))**2))*.48;let eye=Math.abs(x);if(y>-.24&&y<-.09&&eye>.17&&eye<.34)z-=.15;if(Math.abs(x)<.1&&y>-.16&&y<.3)z+=.2*(1-Math.abs(x)/.1);if(y>.45&&y<.53&&Math.abs(x)<.24)z-=.11;pts.push([x,y,z])}}return{c,ctx:c.getContext('2d'),i,pts}})}
function draw(t){faces=faces.filter(f=>f.c.isConnected);for(const f of faces){const {c,ctx,i,pts}=f;const rect=c.getBoundingClientRect();if(!rect.width||!rect.height)continue;const dpr=Math.min(devicePixelRatio||1,2),w=rect.width,h=rect.height;if(c.width!==Math.round(w*dpr)||c.height!==Math.round(h*dpr)){c.width=Math.round(w*dpr);c.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const speaking=c.closest('.speaking')&&state.playing;let a=reduced?0:Math.sin(t*.00045+i*2)*.16;const sz=Math.min(w*.43,h*.43);const color=i===3&&!$('#overlay').hidden?people[state.draft.color].color:getPerson(i).color;ctx.fillStyle=color;for(const [x,y,z]of pts){let yy=y;if(speaking&&y>.35&&y<.64&&Math.abs(x)<.27)yy+=Math.sin(t*.022)*.055;const xx=x*Math.cos(a)+z*Math.sin(a);const zz=z*Math.cos(a)-x*Math.sin(a);const px=w/2+xx*sz,py=h*.49+yy*sz+(reduced?0:Math.sin(t*.001+i)*3);ctx.globalAlpha=.18+zz*.95;const r=(.6+zz*.9)*(speaking?1.1:1);ctx.beginPath();ctx.arc(px,py,r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=.2;ctx.strokeStyle=color;ctx.beginPath();ctx.ellipse(w/2,h*.96,sz*.7,5,0,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}requestAnimationFrame(draw)}
const hash=location.hash.match(/episode-(\d)/);if(hash)state.topic=Math.min(2,Math.max(0,+hash[1]-1));render();
